record.field:
remote = self.remote_id
try:
    cfg = json.loads(remote.connection_params or '{}') or {}
except Exception:
    cfg = {}
api_key = (cfg.get('api_key') or '').strip()
if not api_key:
    raise Exception('Missing DDF api_key in connection_params.')
if isinstance(api_key, unicode):
    api_key = api_key.encode('utf-8')
headers = {b'Authorization': b'API-KEY ' + api_key}
base = (base_url or '').rstrip('/')

# The DDF API may redirect between /resource/id and /resource/id/.
# Try both spellings, but do not forward the API key to an arbitrary
# redirected host. Retain failed requests in the generated report.
def ddf_get(url):
    attempts = []
    for candidate in [url, url[:-1] if url.endswith('/') else url + '/']:
        try:
            response = request_retry(
                'GET', candidate, headers=headers, timeout=timeout,
                allow_redirects=False,
            )
            status = response.status_code
            attempts.append({
                'url': candidate,
                'status': status,
                'location': response.headers.get('Location')
                    if status in (301, 302, 303, 307, 308) else None,
            })
            if status == 200:
                try:
                    payload = response.json() or {}
                except Exception as exc:
                    return None, attempts, 'Invalid JSON: %s' % exc
                if not isinstance(payload, dict):
                    return None, attempts, 'Unexpected JSON root (expected object)'
                return payload, attempts, None
            # A 404 or 307 may be fixed by changing the trailing slash.
            if status in (301, 302, 303, 307, 308, 404, 405):
                continue
            return None, attempts, 'HTTP %s: %s' % (
                status, (response.text or '')[:240],
            )
        except Exception as exc:
            attempts.append({'url': candidate, 'error': str(exc)[:240]})
            # Continue to alternative URL spelling.
    return None, attempts, 'No successful response (see attempts)'

plots_raw, plots_attempts, plots_error = ddf_get(base + '/plots/')
if plots_error:
    raise Exception('DDF /plots/ failed: %s, attempts=%s' % (
        plots_error, plots_attempts,
    ))
plots_raw = plots_raw.get('plots') or []
if not isinstance(plots_raw, list):
    raise Exception('DDF /plots/ returned non-list plots')

plots_list = []
loc_groups = {}
issues = []
total_dataloggers = 0
total_channels = 0
total_channel_ready = 0
failed_dataloggers = 0
plots_without_dataloggers = 0

for plot in plots_raw:
    if not isinstance(plot, dict):
        issues.append({'scope': 'plot', 'error': 'Plot entry is not an object'})
        continue
    plot_id = plot.get('plot_id')
    if plot_id is None:
        issues.append({'scope': 'plot', 'error': 'Missing plot_id'})
        continue
    plot_entry = {
        'plot_id': plot_id,
        'plot_name': plot.get('plot_name') or '',
        'descr': plot.get('descr') or '',
        'loc': plot.get('loc'),
        'report_name': plot.get('report_name') or '',
        'crop_name': plot.get('crop_name') or '',
        'active': plot.get('active', True),
        'dataloggers': [],
    }
    plots_list.append(plot_entry)
    plot_data, plot_attempts, plot_error = ddf_get(
        '%s/plots/%s' % (base, plot_id)
    )
    if plot_error:
        plot_entry['error'] = {
            'message': plot_error,
            'attempts': plot_attempts,
        }
        issues.append({'scope': 'plot_detail', 'plot_id': plot_id,
                       'error': plot_error, 'attempts': plot_attempts})
        loc_key = '__no_loc__'
        loc_groups.setdefault(loc_key, []).append(plot_entry)
        continue

    detail = plot_data.get('plot') or {}
    if not isinstance(detail, dict):
        detail = {}
    plot_entry['res_id'] = detail.get('res_id')
    plot_entry['loc_descr'] = detail.get('loc_descr') or ''
    loc_key = plot_entry['loc_descr'] or '__no_loc__'
    loc_groups.setdefault(loc_key, []).append(plot_entry)

    dl_ids = plot_data.get('dataloggers') or []
    if not isinstance(dl_ids, list):
        plot_entry['error'] = {'message': 'dataloggers is not a list'}
        issues.append({'scope': 'plot_dataloggers', 'plot_id': plot_id,
                       'error': 'dataloggers is not a list'})
        continue
    if not dl_ids:
        plots_without_dataloggers += 1

    for dl in dl_ids:
        mp_id = dl.get('mp_id') if isinstance(dl, dict) else dl
        if mp_id is None or mp_id == '':
            issues.append({'scope': 'datalogger_id', 'plot_id': plot_id,
                           'error': 'Empty mp_id'})
            continue
        datalogger_entry = {
            'mp_id': mp_id,
            'mp_name': '',
            'descr': '',
            'active': None,
            'device_remotecontrol_params': {'datalogger_id': mp_id},
            'channels': [],
        }
        plot_entry['dataloggers'].append(datalogger_entry)
        total_dataloggers += 1

        mp_data, mp_attempts, mp_error = ddf_get(
            '%s/dataloggers/%s/' % (base, mp_id)
        )
        if mp_error:
            failed_dataloggers += 1
            datalogger_entry['error'] = {
                'message': mp_error,
                'attempts': mp_attempts,
            }
            issues.append({
                'scope': 'datalogger', 'plot_id': plot_id, 'mp_id': mp_id,
                'error': mp_error, 'attempts': mp_attempts,
            })
            continue

        mp = mp_data.get('measurement_point') or {}
        if not isinstance(mp, dict):
            mp = {}
        datalogger_entry['mp_name'] = mp.get('mp_name') or ''
        datalogger_entry['descr'] = mp.get('descr') or ''
        datalogger_entry['active'] = mp.get('active', True)
        channels = mp_data.get('channels') or []
        if not isinstance(channels, list):
            datalogger_entry['error'] = {
                'message': 'channels is not a list',
                'attempts': mp_attempts,
            }
            failed_dataloggers += 1
            issues.append({'scope': 'channels', 'plot_id': plot_id,
                           'mp_id': mp_id, 'error': 'channels is not a list'})
            continue
        if not channels:
            datalogger_entry['warning'] = 'No channels returned by DDF'
        for ch in channels:
            if not isinstance(ch, dict):
                issues.append({'scope': 'channel', 'mp_id': mp_id,
                               'error': 'Channel entry is not an object'})
                continue
            dc_id = ch.get('dc_id')
            channel_entry = {
                'dc_id': dc_id,
                'dev_ch_idtext': ch.get('dev_ch_idtext') or '',
                'variable': ch.get('variable') or '',
                'unit': ch.get('unit') or '',
                'depth': ch.get('depth'),
                'model': ch.get('model') or '',
                'sensor_remotecontrol_params': (
                    {'sensor_id': dc_id} if dc_id is not None else None
                ),
            }
            if dc_id is None:
                channel_entry['warning'] = 'Missing dc_id; cannot configure sensor'
            else:
                total_channel_ready += 1
            datalogger_entry['channels'].append(channel_entry)
            total_channels += 1

loc_groups_list = [
    {'loc_descr': key if key != '__no_loc__' else None, 'plots': val}
    for key, val in sorted(
        loc_groups.items(), key=lambda item: (item[0] == '__no_loc__', item[0])
    )
]
report = {
    'procedure': 'DDF: Get Plots',
    'executed_at': fields.Datetime.now(),
    'summary': {
        'total_loc_groups': len(loc_groups_list),
        'total_plots': len(plots_list),
        'total_dataloggers': total_dataloggers,
        'total_channels': total_channels,
        'total_configurable_channels': total_channel_ready,
        'failed_dataloggers': failed_dataloggers,
        'plots_without_dataloggers': plots_without_dataloggers,
        'issues_count': len(issues),
    },
    'loc_groups': loc_groups_list,
    'issues': issues,
}
json_str = json.dumps(report, ensure_ascii=False, indent=2)
encoded = base64.b64encode(json_str.encode('utf-8'))
timestamp = fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_')
fname = 'ddf_plots_%s.json' % timestamp
att = env['ir.attachment'].create({
    'name': fname,
    'datas_fname': fname,
    'datas': encoded,
    'mimetype': 'application/json',
    'res_model': 'remotecontrol',
    'res_id': remote.id,
})
remote.message_post(
    body='[DDF] plots=%s dataloggers=%s channels=%s errors=%s. JSON: %s' % (
        len(plots_list), total_dataloggers, total_channels, len(issues), fname,
    ),
    attachment_ids=[att.id],
)
bag['total_loc_groups'] = len(loc_groups_list)
bag['total_plots'] = len(plots_list)
bag['total_dataloggers'] = total_dataloggers
bag['total_channels'] = total_channels
bag['failed_dataloggers'] = failed_dataloggers
bag['issues_count'] = len(issues)
bag['attachment_name'] = fname

from datetime import timedelta

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
today_str = fields.Date.today()

condition = [
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id),
]
if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))

sensors = Sensor.search(condition)

last_readings_map = {}
if sensors:
    sensor_ids = [s.id for s in sensors]
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for row in cr.fetchall():
        last_readings_map[row[0]] = row[1]

plan = []
for sensor in sensors:
    device = sensor.device_id
    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}
    try:
        device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        device_cfg = {}

    sensor_id_param = sensor_cfg.get('sensor_id')
    datalogger_id = device_cfg.get('datalogger_id')

    if not (sensor_id_param and datalogger_id):
        continue

    start_cfg = sensor_cfg.get('start_date') or device_cfg.get('start_date')

    last_reading_time = last_readings_map.get(sensor.id)
    if last_reading_time:
        try:
            initial_date = str(last_reading_time)[:10]
        except Exception:
            initial_date = today_str
    elif start_cfg:
        initial_date = start_cfg[:10]
    else:
        year_str = today_str[:4]
        initial_date = '%s-01-01' % year_str

    plan.append({
        'sensor_id': sensor.id,
        'device_id': device.id,
        'datalogger_id': datalogger_id,
        'sensor_id_param': sensor_id_param,
        'initial_date': initial_date,
    })

bag['sensors_plan'] = plan
